operations.exampleQuery:
mutation createGroupedOrder {
  createGroupedOrder(
    client_identification: "00000000000000"
    wholesaler: "00000000000000"
    client_code: "1234"
    commercial_condition: ""
    products: [
      { ean: "7891058003203", ordered_quantity: 1, wholesaler_discount: 50 }
      { ean: "7891058003241", ordered_quantity: 2, wholesaler_discount: 40 }
    ]
  ) {
    id
    grouped_order_code
    client_identification
    wholesaler
    client_code
    commercial_condition
    status
    total_products
  }
}

mutation createGroupedCancellation {
  createGroupedCancellation(
    id: 587
    products: [
      { ean: "5000456011624" }
      { ean: "7891000460214" }
    ]
  ) {
    id
    status
  }
}

mutation createGroupedInvoiceReversal {
  createGroupedInvoiceReversal(
    grouped_order_id: 587
    removed_invoices: [351523]
    new_invoices: [
      {
        date_time_processing: "2025-05-06 10:00:00"
        invoice_issue_date: "2025-05-06"
        invoice_number: 351524
        danfe: "BFG102141515"
        invoice_value: 175.00
        invoice_discount_value: 0.00
        products_total_value: 175.00
        invoice_products: [
          { ean: "5000456011624", invoice_quantity: 1, percent_discount: 0.00 }
          { ean: "7891000460214", invoice_quantity: 2, percent_discount: 0.00 }
        ]
      }
    ]
  ) {
    id
    grouped_order_code
    client_identification
    commercial_condition
    client_code
    status
    total_products
    products {
      ean
      ordered_quantity
    }
    invoices {
      processed_at
      number
      danfe
      value
      status
      products {
        ean
        invoice_quantity
      }
    }
  }
}

query {
  groupedOrders(page: 1, limit: 10, filter: { status: AWAITING_ORDER_RESPONSE }) {
    total
    per_page
    current_page
    from
    to
    last_page
    has_more_pages
    data {
      id
      status
      products {
        ean
        ordered_quantity
      }
      responses {
        products {
          ean
          importation_outcome
          product_status
          product_reason
          response_quantity
        }
      }
      invoices {
        products {
          ean
          invoice_quantity
          status
          importation_outcome
        }
      }
      grouped_devolutions {
        invoice_number_devolution
        invoice_devolution_created_at
        cfop
        danfe
        status
        products {
          batch
          code_reason
          ean
          id
          importation_outcome
          quantity
          status
        }
      }
    }
  }
}

query groupedStatusChanges {
  groupedStatusChanges(limit: 50) {
    id
    status
    client_identification
    wholesaler
    total_products
    products {
      ean
      ordered_quantity
    }
    responses {
      status
      processed_at
      products {
        ean
        response_quantity
        importation_outcome
      }
    }
    invoices {
      processed_at
      status
      products {
        ean
        invoice_quantity
        importation_outcome
      }
    }
    cancellations {
      products {
        ean
        importation_outcome
      }
    }
    invoices_reversals {
      products {
        ean
        importation_outcome
      }
    }
  }
}

mutation {
  createGroupedInvoiceDevolution(
    input: {
      grouped_order_id: 123456
      invoice_number: 321654
      invoice_number_devolution: "07042025001"
      invoice_devolution_created_at: "2025-04-07"
      danfe: "TESTE"
      cfop: "TESTE"
      products: [
        { ean: "0000000000004", quantity: 3, batch: "f", code_reason: "201" }
      ]
    }
  ) {
    invoice_number_devolution
    invoice_number
    grouped_order_id
    invoice_devolution_created_at
    cfop
    danfe
    status
    products {
      id
      ean
      batch
      quantity
      code_reason
      status
      importation_outcome
    }
  }
}
